import {KEY} from './seed.js';
import {slots,clinicNow,addDays,dateLabel,money,createBooking,createOrder,whatsappLink,bookingText,orderText} from './store.js';
import {e,icon,modal,toast,error,submit,field,area,empty,download} from './ui.js';
let ctx;
export function initFlows(c){ctx=c;}
const readCart=()=>{try{const c=JSON.parse(localStorage.getItem(KEY+'.cart')||'[]');return Array.isArray(c)?c.filter(x=>x&&typeof x.id==='string'&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=100000):[];}catch{return [];}};
let cart=readCart();
function persistCart(){try{localStorage.setItem(KEY+'.cart',JSON.stringify(cart));}catch{toast('O carrinho será mantido apenas nesta sessão.');}ctx.render();}
export const getCartCount=()=>cart.reduce((n,i)=>n+i.quantity,0);
export function addToCart(id){const p=ctx.getData().products.find(x=>x.id===id&&x.active);if(!p)return toast('Produto indisponível.');const existing=cart.find(x=>x.id===id);if((existing?.quantity||0)>=p.stock)return toast(`Restam ${p.stock} unidades em estoque.`);if(existing)existing.quantity++;else cart.push({id,quantity:1});persistCart();toast('Produto adicionado ao carrinho.');}
function customerFields(v={},notesLabel='Observações (opcional)'){return `${field('name','Nome completo',v.name||'','text','required minlength="2" maxlength="120" autocomplete="name" placeholder="Seu nome completo"')}<div class="form-row">${field('phone','WhatsApp / telefone',v.phone||'','tel','required minlength="8" maxlength="40" autocomplete="tel" placeholder="(11) 99999-9999"')}${field('email','E-mail',v.email||'','email','required maxlength="160" autocomplete="email" placeholder="seu@email.com"')}</div>${area('notes',notesLabel,v.notes||'','maxlength="2000" placeholder="Algo que você gostaria de nos contar?"')}<label class="checkbox-label"><input type="checkbox" name="consent" required ${v.consent?'checked':''}>Autorizo o uso dos meus dados para este atendimento. As informações ficam armazenadas de forma privada para a profissional realizar este atendimento.</label>`;}
export function booking(serviceId='',manual=false){
  let stage=serviceId?1:0,selected=serviceId,date='',time='',details={};const today=clinicNow().date;let month=today.slice(0,7);
  if(!ctx.getData().services.some(s=>s.id===selected&&s.active)){selected='';stage=0;}
  const steps=()=>`<div class="steps">${['Tratamento','Data e horário','Seus dados'].map((t,i)=>`<div class="step ${stage>=i?'active':''}"><b>${i+1}</b>${t}</div>`).join('')}</div>`;
  function show(){const d=ctx.getData(),services=d.services.filter(s=>s.active),s=services.find(x=>x.id===selected);
    if(stage===0){const el=modal(manual?'Registrar pelo WhatsApp':'Agende seu cuidado',`${steps()}<p class="hint" style="margin-bottom:18px">Qual cuidado você precisa?</p>${services.length?services.map(s=>`<button class="service-choice ${selected===s.id?'selected':''}" data-service="${e(s.id)}"><span class="choice-radio"></span><span style="flex:1"><strong>${e(s.title)}</strong><small>${s.duration} minutos · ${money(s.price)}</small></span>${icon('leaf')}</button>`).join(''):empty('Ainda não há tratamentos disponíveis.','leaf')}`,`<span class="hint">Horário de Brasília</span><button class="btn primary" data-next ${!selected?'disabled':''}>Continuar</button>`);el.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{selected=b.dataset.service;date='';time='';show();});el.querySelector('[data-next]').onclick=()=>{stage=1;show();};return;}
    if(!s){stage=0;show();return;}
    if(stage===1){const first=month+'-01',offset=new Date(first+'T12:00:00Z').getUTCDay(),count=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const dates=Array.from({length:count},(_,i)=>`${month}-${String(i+1).padStart(2,'0')}`),times=date?slots(d,s.id,date):[];const title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(first+'T12:00:00Z'));
      const el=modal(manual?'Registrar pelo WhatsApp':'Escolha seu horário',`${steps()}<p class="hint" style="margin-bottom:23px">${e(s.title)} · ${s.duration} min · ${money(s.price)}</p><div class="calendar-head"><button class="icon-btn" data-month="-1" aria-label="Mês anterior" ${month===today.slice(0,7)?'disabled':''}>${icon('chevronLeft')}</button><strong>${e(title)}</strong><button class="icon-btn" data-month="1" aria-label="Próximo mês" ${month>=addDays(today,180).slice(0,7)?'disabled':''}>${icon('chevronRight')}</button></div><div class="calendar" role="group" aria-label="Escolha a data">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(t=>`<span class="weekday">${t}</span>`).join('')}${'<span></span>'.repeat(offset)}${dates.map(day=>`<button ${slots(d,s.id,day).length?'':'disabled'} class="${date===day?'selected':''}" aria-label="${e(dateLabel(day,true))}" aria-pressed="${date===day}" data-date="${day}">${Number(day.slice(-2))}</button>`).join('')}</div><div class="spacer"><p class="field-label">${date?e(dateLabel(date,true)):'Selecione uma data para ver os horários'}</p>${date?times.length?`<div class="time-grid">${times.map(t=>`<button class="${time===t?'selected':''}" aria-pressed="${time===t}" data-time="${t}">${t}</button>`).join('')}</div>`:empty('Não há horários disponíveis nesta data.'):''}<p class="hint spacer">Os horários consideram a duração completa do tratamento. Agenda disponível para os próximos 180 dias.</p></div>`,`<button class="text-btn" data-back>Voltar</button><button class="btn primary" data-next ${!date||!time||!times.includes(time)?'disabled':''}>Continuar</button>`);
      el.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{date=b.dataset.date;time='';show();});el.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{time=b.dataset.time;show();});el.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{const m=new Date(month+'-01T12:00:00Z');m.setUTCMonth(m.getUTCMonth()+Number(b.dataset.month));month=m.toISOString().slice(0,7);show();});el.querySelector('[data-back]').onclick=()=>{stage=0;show();};el.querySelector('[data-next]').onclick=()=>{stage=2;show();};return;
    }
    const el=modal(manual?'Dados do cliente · WhatsApp':'Confirme seu agendamento',`${steps()}<div class="booking-summary"><strong>${e(s.title)}</strong><p>${e(dateLabel(date,true))} · ${time} (Brasília)</p><p>${s.duration} minutos · ${money(s.price)}</p></div><form id="booking-form">${customerFields(details)}${manual?'<p class="hint spacer">Registre apenas com autorização do cliente. Este horário será reservado na mesma agenda do site.</p>':''}<div class="flex spacer" style="justify-content:space-between"><button type="button" class="text-btn" data-back>Voltar</button><button type="submit" class="btn primary">${manual?'Registrar agendamento':'Confirmar agendamento'}</button></div></form>`);
    el.querySelector('[data-back]').onclick=()=>{details=Object.fromEntries(new FormData(el.querySelector('form')));stage=1;show();};submit(el.querySelector('form'),async v=>{details=v;const result=await createBooking({serviceId:selected,date,time,expectedPrice:s.price,expectedDuration:s.duration,customer:{name:v.name.trim(),phone:v.phone.trim(),email:v.email.trim(),notes:v.notes.trim()},consent:v.consent==='on',source:manual?'whatsapp':'online'});confirmation(result,'booking');});
  }show();
}
function confirmation(r,type){const c=ctx.getData().content,isBooking=type==='booking',text=isBooking?bookingText(r):orderText(r),url=whatsappLink(c.phone,text);const el=modal(isBooking?'Agendamento confirmado':'Pedido registrado',`<div class="success"><div class="success-icon">${icon('check')}</div><h3>${isBooking?'Seu cuidado está agendado.':'Obrigado pelo seu pedido!'}</h3><p>${isBooking?'Seu horário foi reservado e a notificação foi registrada no painel da profissional.':'Seu pedido está pendente de pagamento. Combine o pagamento e o recebimento com o consultório.'}</p><div class="booking-summary">${isBooking?`<strong>${e(r.serviceTitle)}</strong><p>${e(dateLabel(r.date,true))} às ${r.time}</p><p>${r.duration} min · ${money(r.price)}</p>`:`<strong>Pedido #${e(r.id.slice(0,8))}</strong><p>${r.items.map(i=>`${i.quantity} × ${e(i.title)}`).join('<br>')}</p><p>Total: ${money(r.total)}</p>`}<p class="hint">Código: ${e(r.id.slice(0,8))}</p></div>${url?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer" class="btn primary">${icon('whatsapp')}${isBooking?'Enviar confirmação pelo WhatsApp':'Combinar pagamento pelo WhatsApp'}</a>`:'<p class="hint">O WhatsApp do consultório ainda não foi cadastrado.</p>'}<button class="btn secondary" data-save>${icon('download')} Salvar comprovante</button><p class="hint">O WhatsApp abre uma mensagem pronta; você decide quando enviá-la. A profissional recebe o aviso no painel. O site não envia e-mail automaticamente.</p></div>`,`<span></span><button class="btn secondary" data-done>Concluir</button>`);el.querySelector('[data-save]').onclick=()=>download(`${isBooking?'agendamento':'pedido'}-${r.id.slice(0,8)}.txt`,text,'text/plain;charset=utf-8');el.querySelector('[data-done]').onclick=()=>el.close();}
export function productDetail(id){const p=ctx.getData().products.find(x=>x.id===id&&x.active);if(!p)return toast('Produto indisponível.');const el=modal(p.title,`<div class="product-detail">${p.image?`<img src="${e(p.image)}" alt="${e(p.title)}" width="250" height="250">`:`<div class="cart-thumb">${icon('box')}</div>`}<div><p class="product-category">${e(p.category)}</p><p>${e(p.description)}</p><p class="spacer"><strong>${money(p.price)}</strong></p><p class="hint">${p.stock?`${p.stock} unidades disponíveis`:'Produto esgotado'}</p></div></div>`,`<button class="text-btn" data-cart>${icon('bag')} Ver carrinho</button><button class="btn primary" data-add ${!p.stock?'disabled':''}>${icon('plus')} Adicionar ao carrinho</button>`);el.querySelector('[data-add]').onclick=()=>addToCart(id);el.querySelector('[data-cart]').onclick=cartModal;}
export function cartModal(){const d=ctx.getData(),rows=cart.map(i=>({...i,product:d.products.find(p=>p.id===i.id)})),total=rows.reduce((n,i)=>n+(i.product?.price||0)*i.quantity,0);const el=modal('Seu carrinho',`${rows.length?rows.map(i=>`<div class="cart-row"><div class="cart-thumb">${i.product?.image?`<img src="${e(i.product.image)}" alt="${e(i.product.title)}">`:icon('box')}</div><div class="cart-info"><strong>${e(i.product?.title||'Produto removido')}</strong><small>${i.product?money(i.product.price):'Indisponível'}</small>${!i.product?.active||i.quantity>i.product.stock?'<p class="hint" style="color:#a52b34">Revise este item: indisponível ou estoque insuficiente.</p>':''}</div><div class="quantity"><button data-qty="-1" data-id="${e(i.id)}" aria-label="Diminuir quantidade">−</button><span>${i.quantity}</span><button data-qty="1" data-id="${e(i.id)}" aria-label="Aumentar quantidade" ${!i.product?.active||i.quantity>=i.product.stock?'disabled':''}>+</button></div><button class="text-btn" data-remove="${e(i.id)}" aria-label="Remover ${e(i.product?.title)}">${icon('trash')}</button></div>`).join('')+`<div class="total-row"><strong>Subtotal</strong><strong>${money(total)}</strong></div><p class="hint">Pagamento combinado com o consultório. Entrega e eventual frete serão confirmados antes do pagamento.</p>`:empty('Seu carrinho está esperando um pouco de cuidado.','bag')}`,`<button class="text-btn" data-continue>Continuar comprando</button><button class="btn primary" data-checkout ${!rows.length?'disabled':''}>Finalizar pedido</button>`);
  el.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const i=cart.find(x=>x.id===b.dataset.id);i.quantity+=Number(b.dataset.qty);cart=cart.filter(x=>x.quantity>0);persistCart();cartModal();});el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!==b.dataset.remove);persistCart();cartModal();});el.querySelector('[data-continue]').onclick=()=>{el.close();location.hash='#/loja';};el.querySelector('[data-checkout]').onclick=()=>{if(rows.some(i=>!i.product?.active||i.quantity>i.product.stock))return error(new Error('Revise os produtos indisponíveis no seu carrinho.'));checkout();};
}
function checkout(){const rows=cart.map(i=>({...i,product:ctx.getData().products.find(p=>p.id===i.id)}));const total=rows.reduce((n,i)=>n+Math.round((i.product?.price||0)*100)*i.quantity,0)/100;const el=modal('Finalize seu pedido',`<div class="booking-summary"><strong>Resumo do pedido</strong>${rows.map(i=>`<p>${i.quantity} × ${e(i.product?.title||'Produto indisponível')} · ${money((i.product?.price||0)*i.quantity)}</p>`).join('')}<p><strong>Total: ${money(total)}</strong></p></div><form id="checkout-form">${customerFields({},'Observações do pedido (opcional)')}<div class="field-label">Como deseja receber?</div><div class="delivery-options"><label><input type="radio" name="delivery" value="pickup" checked>Retirar no consultório</label><label><input type="radio" name="delivery" value="delivery">Combinar entrega</label></div><div id="delivery-address" hidden>${area('address','Endereço completo','','maxlength="500" placeholder="Rua, número, bairro, cidade e CEP"')}</div><div class="notice">Este pedido será registrado como pendente. Nenhuma cobrança é feita pelo site. Confirme com o consultório a forma de pagamento e a entrega.</div><div class="flex" style="justify-content:space-between"><button type="button" class="text-btn" data-back>Voltar ao carrinho</button><button type="submit" class="btn primary">Registrar pedido</button></div></form>`);el.querySelector('[data-back]').onclick=cartModal;el.querySelectorAll('[name=delivery]').forEach(r=>r.onchange=()=>{const delivery=el.querySelector('[name=delivery]:checked').value==='delivery';el.querySelector('#delivery-address').hidden=!delivery;el.querySelector('[name=address]').required=delivery;if(delivery)el.querySelector('[name=address]').setAttribute('minlength','10');});submit(el.querySelector('form'),async v=>{const o=await createOrder({cart:structuredClone(cart),expectedTotal:total,customer:{name:v.name.trim(),phone:v.phone.trim(),email:v.email.trim(),notes:v.notes.trim()},consent:v.consent==='on',delivery:v.delivery,address:v.address});cart=[];persistCart();confirmation(o,'order');});}
